{
  "status": "updated",
  "chapter_updates": [
    {
      "chapter_id": "CH1",
      "updated_plan": {
        "thesis": "可见光消色差超构透镜的带宽与视场性能受限于两个独立的物理边界：一是基于局部相位调控的延迟 - 带宽积极限，其随数值孔径（NA）增加而收紧，但因有限孔径导致的群延迟需求非单调性而在大视场下出现饱和；二是单界面几何结构无法校正高阶像差（如彗差、场曲），导致高 NA 下的有效成像视场极小（如 NA=0.5 时<5 µm）。这两重限制共同确立了单层超构透镜在宽视场高性能成像中的理论天花板。",
        "reader_objective": "读者应理解‘大视场必然导致带宽线性崩溃’是误区，实际存在带宽饱和现象；同时认识到即使色散完美校正，单界面几何像差仍会严重限制高 NA 器件的有效视场（具体量化为 NA=0.5 时视场<5 µm），从而为后续章节探讨微观设计机制和实证评估提供明确的物理约束背景。",
        "units": [
          {
            "unit_id": "U1",
            "theme": "延迟 - 带宽积作为基本物理约束",
            "substantive_point": "确立局部超表面中最大群延迟范围决定可用带宽上限的基本不等式，并阐明高 NA 如何压缩这一上限。",
            "development": "从一维延迟线模型出发，推导ΔT · Δω ≤ κ的物理基础，论证ΔT_max 随 NA 增加而急剧扩大的趋势。",
            "paragraph_briefs": [
              {
                "point": "引入延迟 - 带宽积极限及其在超构原子层面的物理意义。",
                "development": "将每个超构原子建模为一维延迟线，引用 P0002 的核心推导，指出局部相互作用下的基本不等式ΔT · Δω ≤ κ，其中κ由材料对比度和结构长度决定。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "论证高 NA 对最大群延迟范围的压缩效应。",
                "development": "分析消色差设计中，为了补偿不同波长下的相位差，所需的群延迟跨度随 NA 增加而扩大，说明这是高 NA 器件带宽受限的首要原因。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "conditions_and_limits": "该推导基于标量近似和局部相位假设；在极高 NA 或亚波长尺度下，矢量衍射效应可能引入修正，但定性趋势保持不变。",
            "transition": "明确了带宽随 NA 增加的下降趋势后，需进一步分析视场角（FOV）对带宽的具体影响，以澄清常见的线性衰退预期。"
          },
          {
            "unit_id": "U2",
            "theme": "群延迟需求的非单调性与带宽饱和机制",
            "substantive_point": "揭示有限孔径金属透镜上群延迟需求的非单调性，解释带宽随 FOV 增加先减小后饱和的现象。",
            "development": "反驳直觉认为入射角越大所需补偿越大的观点，通过 P0002 的数值结果展示群延迟极差在特定临界角达到峰值后减小的过程。",
            "paragraph_briefs": [
              {
                "point": "阐述有限孔径下群延迟分布的空间特性。",
                "development": "基于 P0002 的分析，指出随着 FOV 增加，透镜面上所需的最大群延迟差值先增大，在特定临界角α*达到峰值，随后因有效孔径截断和光程差变化率降低而减小。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "定义并解释‘带宽饱和’现象。",
                "development": "论证当工作 FOV 超过覆盖α*的临界值后，决定带宽下限的ΔT_max 不再随 FOV 增加而显著增加，导致带宽界限趋于稳定而非无限下降。例如，对于固定 NA=0.7nb，180 度视场的理论带宽上限可能与 60 度视场相当。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "conditions_and_limits": "饱和点的具体位置依赖于 NA 值和焦点定义方式；此结论修正了简单的线性衰退预期，表明在大视场区域存在优化的理论空间。文中未给出临界 FOV 的解析公式，仅通过数值计算展示其存在。",
            "transition": "既然饱和现象具有普遍性，需进一步考察不同的焦点映射几何是否会影响这一核心物理趋势。"
          },
          {
            "unit_id": "U3",
            "theme": "焦点几何映射对带宽界限的影响",
            "substantive_point": "对比无畸变与有畸变两种焦点定位策略，确认带宽饱和是有限孔径系统的内禀属性。",
            "development": "比较 r0 = F tan(α) 与 r0 = F α两种情况，分析绝对数值的差异但强调饱和趋势的一致性。",
            "paragraph_briefs": [
              {
                "point": "对比两种焦点定位策略的理论差异。",
                "development": "分析 r0 = F tan(α)（无畸变）与 r0 = F α（线性映射）的计算结果，指出无畸变要求通常更严苛，但两者均表现出随 FOV 增加而饱和的趋势。",
                "source_handles": [
                  "P0002"
                ]
              },
              {
                "point": "确认饱和现象的内禀属性。",
                "development": "总结表明饱和现象并非特定成像标准的产物，而是有限孔径系统在面对大角度入射时的几何与波动光学共同作用的结果。",
                "source_handles": [
                  "P0002"
                ]
              }
            ],
            "conditions_and_limits": "实际应用中需根据成像质量要求选择对应的理论界限，但两者均受同一饱和机制支配。",
            "transition": "尽管色散工程可以克服带宽限制，但单层结构还面临另一重独立的几何像差限制，这构成了 FOV 的另一重硬边界。"
          },
          {
            "unit_id": "U4",
            "theme": "单界面几何像差的独立硬限制",
            "substantive_point": "指出即使色散完美校正，单层超构透镜仍受限于单界面几何无法校正高阶像差，导致高 NA 下有效视场极小（<5 µm）。",
            "development": "结合 P0001 的视角，从几何光学角度解释彗差、像散和场曲的产生，并引用具体数值估算量化其对成像质量的破坏。",
            "paragraph_briefs": [
              {
                "point": "解释单界面几何像差的产生机制。",
                "development": "基于 P0001 的论述，指出单层结构缺乏空间自由度来补偿斜入射带来的路径延迟误差，导致彗差、像散和场曲随 NA 和视场角迅速增大。展开理想相位差公式可得到标准的像差项。",
                "source_handles": [
                  "P0001"
                ]
              },
              {
                "point": "量化高 NA 下的视场限制。",
                "development": "引用 P0001 的具体数据：对于 NA=0.5、焦距 1mm 的超构透镜，在可见光范围内路径延迟误差不超过一个波长的低像差视场被限制在小于 5 µm。这解释了为何单纯优化色散不足以实现宽视场高性能成像，且将单透镜与多片式商用物镜直接对比是不恰当的。",
                "source_handles": [
                  "P0001"
                ]
              }
            ],
            "conditions_and_limits": "此限制针对单层结构；多层或复合系统可缓解此问题，但不在本章主要讨论范围内。该数值估算是基于几何光学推导的理论上限，实际器件可能受制造误差影响更小。",
            "transition": "本章确立了宏观物理界限，下一章将深入微观层面，探讨为了实现这些色散补偿所采用的纳米结构设计是如何引入效率损耗的。"
          }
        ]
      }
    }
  ],
  "unit_id_remap": {}
}

